<?php
/** Synthetic final valuation/cutover fixtures; no external providers. */
declare(strict_types=1);
if(!defined('TGIT_DISPOSABLE_TEST_SITE')||TGIT_DISPOSABLE_TEST_SITE!==true)throw new RuntimeException('Disposable site required.');
use GainerInteractive\IGTradingJournal\Application\TickerbotStore;
use GainerInteractive\IGTradingJournal\Application\PricingPolicy;
use GainerInteractive\IGTradingJournal\Infrastructure\TickerbotConnectionCheck;

function tbf_context():array{
 global $tracker,$db,$owner;$w=(int)$tracker->create_workspace(['name'=>'Build cutover fixture'])['id'];$scope=TGIT_TICKERBOT_ACCOUNT_SCOPE;
 $db->query('UPDATE '.$db->table('tickerbot_accounts').' SET monthly_cap=8000,lease_until=%s,paused_until=NULL,pause_kind=NULL,recovery_not_before=NULL WHERE scope_digest=%s',['2000-01-01 00:00:00',hash('sha256','tickerbot/account/'.$scope)]);
 $s=new TickerbotStore($db,$owner,wp_generate_uuid4(),$scope);$s->configure($w);$asset=tbi_asset($w,'AAPL');$s->save_mapping($w,$asset,'AAPL',tb_row('AAPL'));$account=(int)$tracker->create_object($w,'accounts',['name'=>'Synthetic USD','native_currency'=>'USD'])['id'];$tracker->post($w,['account_id'=>$account,'action'=>'deposit','effective_date'=>'2026-01-01','state'=>'posted','amount'=>'2000','currency'=>'USD'],'build-fund');$tracker->post($w,['account_id'=>$account,'asset_id'=>$asset,'action'=>'buy','effective_date'=>'2026-01-02','state'=>'posted','quantity'=>'10','unit_price'=>'100','fees'=>'0','currency'=>'USD'],'build-buy');
 return [$s,$w,$asset,$account,new PricingPolicy($db,$owner,wp_generate_uuid4())];
}
function tbf_mark($s,int $w,array $marks):array{
 global $db;$db->query('UPDATE '.$db->table('tickerbot_settings').' SET last_manual_at=%s WHERE workspace_id=%d',['2000-01-01 00:00:00',$w]);$r=$s->start_run($w,wp_generate_uuid4());if(!isset($r['lease_token']))throw new RuntimeException('Synthetic mark run not created: '.json_encode($r));$maps=[];foreach($marks as$id=>$v){$maps[$id]=$db->row('SELECT * FROM '.$db->table('tickerbot_mappings').' WHERE workspace_id=%d AND asset_id=%d ORDER BY id DESC LIMIT 1',[$w,$id]);}$a=$s->reserve_attempt($w,$r['run_id'],$r['lease_token'],'quotes',array_column($maps,'provider_symbol'));if($a['state']!=='admitted')throw new RuntimeException('Synthetic mark not admitted: '.json_encode($a));
 foreach($marks as$id=>[$price,$time]){$now=new DateTimeImmutable('now',new DateTimeZone('UTC'));$asof=$time==='recent'?$now->modify('-30 seconds')->format('Y-m-d H:i:s.u'):$time;if(is_string($asof)&&strlen($asof)===19)$asof.='.000000';$s->record_quote($w,$r['run_id'],$r['lease_token'],$a['attempt_id'],(int)$maps[$id]['id'],['asset_id'=>$id,'provider'=>'tickerbot','provider_symbol'=>$maps[$id]['provider_symbol'],'currency'=>$maps[$id]['currency'],'price'=>$price,'price_source'=>'fair_value','price_asof'=>$asof,'response_as_of'=>$now->format('Y-m-d H:i:s.u'),'fetched_at'=>$now->format('Y-m-d H:i:s.u'),'source_time_semantics'=>$asof===null?'unknown':'provider_fetch_time']);}
 $s->finish_attempt($w,$r['run_id'],$r['lease_token'],$a['attempt_id'],'completed');$s->finish_run($w,$r['run_id'],$r['lease_token'],'completed');return $r;
}
function tbf_ready($s,int $w,int $asset):void{
 global $db;$db->query('UPDATE '.$db->table('tickerbot_settings').' SET last_manual_at=%s WHERE workspace_id=%d',['2000-01-01 00:00:00',$w]);$connection=TickerbotConnectionCheck::run($s,$w,wp_generate_uuid4(),fn()=>['headers'=>[],'response'=>['code'=>200],'body'=>json_encode(['ticker'=>'AAPL','data'=>tb_row('AAPL'),'as_of'=>gmdate('Y-m-d\TH:i:s\Z')])]);equal($connection['state'],'connected');tbf_mark($s,$w,[$asset=>['125','recent']]);
}
function tbf_switch($p,int $w):array{$r=$p->review($w);if(!$r['ready'])throw new RuntimeException('Synthetic readiness blocked: '.json_encode($r));return $p->save($w,'tickerbot',$r['policy']['revision'],true,$r['settings_revision'],$r['scope_revision']);}

test('Tickerbot cache values holdings exactly without changing ledger or historical manual evidence',function()use($tracker,$db){
 [$s,$w,$asset,$account,$p]=tbf_context();tbf_mark($s,$w,[$asset=>['125.123456789123456789','recent']]);$before=$tracker->list_objects($w,'transactions');$h=$tracker->holdings($w,0,100,'tickerbot')['items'][0];decimal($h['market_value'],'1251.234567891234567890');decimal($h['unrealized_gain'],'251.234567891234567890');equal($h['price_status'],'complete');equal($h['price_observation']['source_time_semantics'],'provider_fetch_time');equal($tracker->holdings($w,0,100,'workspace')['items'][0]['market_value'],null);equal($tracker->list_objects($w,'transactions'),$before);equal($db->rows('SELECT id FROM '.$db->table('market_observations').' WHERE workspace_id=%d',[$w]),[]);
});
test('Tickerbot stale unknown and changed mappings never silently use manual or another provider',function()use($tracker){
 [$s,$w,$asset,$account,$p]=tbf_context();$today=(new DateTimeImmutable('now',new DateTimeZone('America/New_York')))->format('Y-m-d');$tracker->record_observation($w,['kind'=>'price','asset_id'=>$asset,'currency'=>'USD','value'=>'999','effective_date'=>$today,'expires_on'=>$today,'source'=>'Synthetic manual','reason'=>'Explicit override'],'fallback-fixture');
 foreach([[gmdate('Y-m-d H:i:s',time()-86400),'stale'],[null,'unknown']]as[$time,$state]){tbf_mark($s,$w,[$asset=>['125',$time]]);$h=$tracker->holdings($w,0,100,'tickerbot')['items'][0];equal($h['price_status'],$state);equal($h['market_value'],null);equal($h['unrealized_gain'],null);}decimal($tracker->holdings($w,0,100,'manual')['items'][0]['market_value'],'9990');$latest=$s->controls($w)['inventory']['items'][0]['mapping_id'];$s->save_mapping($w,$asset,'AAPL',tb_row('AAPL'),$latest);equal($tracker->holdings($w,0,100,'tickerbot')['items'][0]['market_value'],null);
});
test('Tickerbot cutover is acknowledged revisioned reversible and preserves legacy schedules',function()use($tracker,$db,$owner){
 [$s,$w,$asset,$account,$p]=tbf_context();$p->save($w,'fmp',0,true);tbs_denied(fn()=>$p->save($w,'tickerbot',1,false));equal($p->review($w)['ready'],false);tbf_ready($s,$w,$asset);$before=$s->usage($w)['attempts'];$policy=tbf_switch($p,$w);equal($policy['source'],'tickerbot');equal($policy['previous_source'],'fmp');decimal($tracker->holdings($w,0,100,'workspace')['items'][0]['market_value'],'1250');$summary=$tracker->stock_summary($w,'workspace');decimal($summary['currency_groups'][0]['market_value'],'1250');equal($summary['currency_groups'][0]['status'],'complete');equal($p->save($w,'rollback',2,true)['source'],'fmp');equal($s->usage($w)['attempts'],$before);equal($tracker->holdings($w,0,100,'workspace')['items'][0]['market_value'],null);$stale=false;try{$p->save($w,'manual',2,true);}catch(UnexpectedValueException $e){$stale=true;}equal($stale,true);equal(count($db->rows('SELECT id FROM '.$db->table('pricing_policies').' WHERE workspace_id=%d',[$w])),3);
});
test('Tickerbot policy change fences old queued manual batches without another admission',function()use($db){
 [$s,$w,$asset,$account,$p]=tbf_context();tbf_ready($s,$w,$asset);tbf_switch($p,$w);$r=$s->controls($w);$db->query('UPDATE '.$db->table('tickerbot_settings').' SET last_manual_at=%s WHERE workspace_id=%d',['2000-01-01 00:00:00',$w]);$run=$s->start_run($w,wp_generate_uuid4(),'manual',0,$r['settings_revision'],$r['selection']['revision']);equal($s->next_dispatch($w,$run['run_id'],$run['lease_token'])['state'],'ready');$before=$s->usage($w)['attempts'];$p->save($w,'rollback',1,true);tbs_denied(fn()=>$s->next_dispatch($w,$run['run_id'],$run['lease_token']));equal($s->usage($w)['attempts'],$before);$s->finish_run($w,$run['run_id'],$run['lease_token'],'failed');
});
test('Tickerbot manual refresh binds reviewed inputs and duplicate keys cannot create another run',function()use($db){
 [$s,$w,$asset,$account,$p]=tbf_context();$r=$s->controls($w);$counted=$s->usage($w)['attempts'];$key=wp_generate_uuid4();$one=\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotManual::run($s,$w,$key,$r['settings_revision'],$r['selection']['revision']);equal($one['state'],'running');equal(isset($one['lease_token']),false);$again=\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotManual::run($s,$w,$key,$r['settings_revision'],$r['selection']['revision']);equal($again['run_id'],$one['run_id']);equal($s->usage($w)['attempts'],$counted);equal(count($db->rows('SELECT id FROM '.$db->table('tickerbot_plans').' WHERE workspace_id=%d',[$w])),1);tbs_denied(fn()=>\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotManual::run($s,$w,$key,$r['settings_revision']+1,$r['selection']['revision']));wp_clear_scheduled_hook('tgit_tickerbot_batch',[$w,$one['run_id']]);
});
test('Tickerbot switch audit failure leaves the source and prior history intact',function()use($db,$wpdb){
 [$s,$w,$asset,$account,$p]=tbf_context();$trigger='fixture_switch_'.bin2hex(random_bytes(4));$db->query('CREATE TRIGGER '.$trigger.' BEFORE INSERT ON '.$db->table('audit_events')." FOR EACH ROW BEGIN IF NEW.action='pricing.switch' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic'; END IF; END");$prior=$wpdb->suppress_errors(true);try{$failed=false;try{$p->save($w,'fmp',0,true);}catch(RuntimeException $e){$failed=true;}equal($failed,true);}finally{$db->query('DROP TRIGGER '.$trigger);$wpdb->suppress_errors($prior);}equal($p->get($w)['revision'],0);equal($p->get($w)['source'],'manual');
});

test('Tickerbot active policy blocks legacy quote reservation and dispatch while fundamentals remain available',function()use($db,$owner){
 [$s,$w,$asset,$account,$p]=tbf_context();$legacy=new \GainerInteractive\IGTradingJournal\Application\MarketData($db,$owner,wp_generate_uuid4());$map=$legacy->save_mapping($w,$asset,['provider'=>'alpha_vantage','provider_symbol'=>'AAPL','exchange'=>'XNAS','currency'=>'USD','enabled'=>true,'evidence'=>'Synthetic compatible identity','expected_mapping_id'=>0]);$fingerprint=hash('sha256',wp_generate_uuid4());$reserved=$legacy->reserve($w,(int)$map['id'],$fingerprint,'before-switch');$schedule=$legacy->save_schedule($w,(int)$map['id'],['frequency'=>'once','expected_schedule_id'=>0]);tbf_ready($s,$w,$asset);tbf_switch($p,$w);$before=$legacy->schedule_config($w,(int)$map['id']);tbs_denied(fn()=>$legacy->dispatch($w,(int)$reserved['id']));tbs_denied(fn()=>$legacy->reserve($w,(int)$map['id'],$fingerprint,'after-switch'));equal($legacy->reserve($w,(int)$map['id'],$fingerprint,'fundamentals-unchanged',true,'OVERVIEW')['state'],'reserved');equal(\GainerInteractive\IGTradingJournal\Infrastructure\RecurringQuotes::queue($w,(int)$schedule['id']),false);$p->save($w,'rollback',1,true);equal($legacy->schedule_config($w,(int)$map['id']),$before);equal($legacy->reserve($w,(int)$map['id'],$fingerprint,'after-rollback')['state'],'reserved');
});
test('Tickerbot crypto ETF and foreign-currency holdings stay native and stock totals never invent FX',function()use($tracker){
 [$s,$w,$asset,$account,$p]=tbf_context();$crypto=(int)$tracker->create_object($w,'assets',['symbol'=>'BTC','exchange'=>'SYNTHETIC','asset_class'=>'crypto','quote_currency'=>'USD'])['id'];$row=tb_row('X:BTCUSD');$row['asset_class']='crypto';$s->save_mapping($w,$crypto,'X:BTCUSD',$row);$tracker->post($w,['account_id'=>$account,'asset_id'=>$crypto,'action'=>'buy','effective_date'=>'2026-01-03','state'=>'posted','quantity'=>'0.01','unit_price'=>'10000','fees'=>'0','currency'=>'USD'],'crypto-lot');$etf=(int)$tracker->create_object($w,'assets',['symbol'=>'ETF','exchange'=>'XNAS','asset_class'=>'etf','quote_currency'=>'USD'])['id'];$row=tb_row('ETF');$row['asset_type']='ETF';$s->save_mapping($w,$etf,'ETF',$row);$tracker->post($w,['account_id'=>$account,'asset_id'=>$etf,'action'=>'buy','effective_date'=>'2026-01-03','state'=>'posted','quantity'=>'1','unit_price'=>'100','fees'=>'0','currency'=>'USD'],'etf-position');$euro=(int)$tracker->create_object($w,'accounts',['name'=>'Synthetic EUR','native_currency'=>'EUR'])['id'];$eur=(int)$tracker->create_object($w,'assets',['symbol'=>'EURSTOCK','exchange'=>'XNAS','asset_class'=>'stock','quote_currency'=>'EUR'])['id'];$row=tb_row('EURSTOCK');$row['currency_name']='eur';$s->save_mapping($w,$eur,'EURSTOCK',$row);$tracker->post($w,['account_id'=>$euro,'action'=>'deposit','effective_date'=>'2026-01-01','state'=>'posted','amount'=>'1000','currency'=>'EUR'],'eur-fund');$tracker->post($w,['account_id'=>$euro,'asset_id'=>$eur,'action'=>'buy','effective_date'=>'2026-01-02','state'=>'posted','quantity'=>'2','unit_price'=>'100','fees'=>'0','currency'=>'EUR'],'eur-position');tbf_mark($s,$w,[$asset=>['125','recent'],$crypto=>['50000','recent'],$etf=>['200','recent'],$eur=>['150','recent']]);$h=$tracker->holdings($w,0,100,'tickerbot');$by=array_column($h['items'],null,'asset_id');decimal($by[$crypto]['market_value'],'500');decimal($by[$etf]['market_value'],'200');decimal($by[$eur]['market_value'],'300');equal($h['base_totals'],null);$g=$tracker->stock_summary($w,'tickerbot')['currency_groups'];equal(array_column($g,'currency'),['EUR','USD']);decimal($g[0]['market_value'],'300');decimal($g[1]['market_value'],'1250');
});
test('Pricing schema 28 upgrade repeat and owner isolation preserve financial rows and policy revisions',function()use($db,$tracker,$viewer){
 [$s,$w,$asset,$account,$p]=tbf_context();$p->save($w,'fmp',0,true);$before=$tracker->list_objects($w,'transactions');update_option('tgit_schema_version','27');\GainerInteractive\IGTradingJournal\Infrastructure\Installer::install();\GainerInteractive\IGTradingJournal\Infrastructure\Installer::install();equal(get_option('tgit_schema_version'),'28');equal($p->get($w)['source'],'fmp');equal($tracker->list_objects($w,'transactions'),$before);$untrusted=new PricingPolicy($db,$viewer,wp_generate_uuid4());tbs_denied(fn()=>$untrusted->save($w,'manual',1,true));tbs_denied(fn()=>$untrusted->review($w));
});

test('Final synthetic package browser references are ready without sending live provider requests',function()use($db,$owner,$viewer){
 [$s,$w,$asset,$account,$p]=tbf_context();tbf_ready($s,$w,$asset);$p->save($w,'alpha_vantage',0,true);$db->query('UPDATE '.$db->table('tickerbot_settings').' SET last_manual_at=%s WHERE workspace_id=%d',['2000-01-01 00:00:00',$w]);file_put_contents(dirname(__DIR__).'/tmp/tickerbot-package-fixtures.json',json_encode(['owner'=>$owner,'viewer'=>$viewer,'workspace'=>$w,'asset'=>$asset,'account'=>$account,'scope'=>TGIT_TICKERBOT_ACCOUNT_SCOPE]));equal($p->review($w)['ready'],true);
});

test('Cutover waits for a dispatched legacy request and rollback stops subsequent scheduled Tickerbot work',function()use($db,$owner){
 [$s,$w,$asset,$account,$p]=tbf_context();$legacy=new \GainerInteractive\IGTradingJournal\Application\MarketData($db,$owner,wp_generate_uuid4());$map=$legacy->save_mapping($w,$asset,['provider'=>'alpha_vantage','provider_symbol'=>'AAPL','exchange'=>'XNAS','currency'=>'USD','enabled'=>true,'evidence'=>'Synthetic legacy identity','expected_mapping_id'=>0]);$req=$legacy->reserve($w,(int)$map['id'],hash('sha256',wp_generate_uuid4()),'inflight-guard');$legacy->dispatch($w,(int)$req['id']);tbf_ready($s,$w,$asset);equal(in_array('legacy_inflight',$p->review($w)['blockers'],true),true);tbs_denied(fn()=>$p->save($w,'tickerbot',0,true,1,0));$legacy->complete_alpha_quote($w,(int)$req['id'],json_encode(['Global Quote'=>['01. symbol'=>'AAPL','05. price'=>'125','08. previous close'=>'120','07. latest trading day'=>gmdate('Y-m-d')]]));tbf_switch($p,$w);$s->save_cadence($w,true,0,1,0);$p->save($w,'rollback',1,true);$before=$db->rows('SELECT id FROM '.$db->table('tickerbot_runs').' WHERE workspace_id=%d',[$w]);\GainerInteractive\IGTradingJournal\Infrastructure\RecurringTickerbot::job($w);equal($db->rows('SELECT id FROM '.$db->table('tickerbot_runs').' WHERE workspace_id=%d',[$w]),$before);equal(\GainerInteractive\IGTradingJournal\Infrastructure\RecurringTickerbot::queue($w),false);
});

test('Recurring Tickerbot cannot queue before explicit workspace activation even with all server flags on',function(){
 [$s,$w,$asset,$account,$p]=tbf_context();$s->save_cadence($w,true,0);equal($p->get($w)['source'],'manual');equal(\GainerInteractive\IGTradingJournal\Infrastructure\RecurringTickerbot::queue($w),false);
});
